     9	public final class FinanceNotifier implements ReservationListener {
    10	    private static final String EMAIL = "financeiro@pousadamarealta.com.br";
    11	    private final MessageSender messageSender;
    12	
    13	    public FinanceNotifier(MessageSender messageSender) {
    14	        this.messageSender = messageSender;
    15	    }
    16	
    17	    @Override
    18	    public void onEvent(ReservationEvent event) {
    19	        switch (event) {
    20	            case ReservationEvent.Confirmed confirmed ->
    21	                notifyPayment(confirmed.reservation());
    22	            case ReservationEvent.Cancelled cancelled when cancelled.wasConfirmed() && hasRefund(cancelled.reservation()) ->
    23	                notifyRefund(cancelled.reservation());
    24	            default -> {}
    25	        }
    26	    }
    27	
    28	    private boolean hasRefund(Reservation reservation) {
    29	        return reservation.refund() != null && reservation.refund().compareTo(BigDecimal.ZERO) > 0;
    30	    }
    31	
    32	    private void notifyPayment(Reservation reservation) {
    33	        String body = String.format("Valor: %s", formatMoney(reservation.amountPaid()));
    34	
    35	        messageSender.send(
    36	            MessageChannel.EMAIL,
    37	            EMAIL,
    38	            String.format("Pagamento recebido - reserva %d", reservation.id()),
    39	            body
    40	        );
    41	    }
    42	
    43	    private void notifyRefund(Reservation reservation) {
    44	        String body = String.format("Valor: %s", formatMoney(reservation.refund()));
    45	
    46	        messageSender.send(
    47	            MessageChannel.EMAIL,
    48	            EMAIL,
    49	            String.format("Reembolso - reserva %d", reservation.id()),
    50	            body
    51	        );
    52	    }
    53	
    54	    private String formatMoney(BigDecimal amount) {
    55	        return String.format(Locale.of("pt", "BR"), "R$ %,.2f", amount);
    56	    }
    57	}
