     1	package com.pousadamarealta.notification;
     2	
     3	import com.pousadamarealta.domain.MessageChannel;
     4	import com.pousadamarealta.domain.Reservation;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	import java.time.format.DateTimeFormatter;
     9	import java.util.Locale;
    10	
    11	public final class GuestNotifier implements ReservationListener {
    12	    private final MessageSender messageSender;
    13	
    14	    public GuestNotifier(MessageSender messageSender) {
    15	        this.messageSender = messageSender;
    16	    }
    17	
    18	    @Override
    19	    public void onEvent(ReservationEvent event) {
    20	        if (event instanceof ReservationEvent.Confirmed confirmed) {
    21	            sendConfirmationEmail(confirmed.reservation());
    22	        }
    23	    }
    24	
    25	    private void sendConfirmationEmail(Reservation reservation) {
    26	        String receipt = buildReceipt(reservation);
    27	        String body = String.format("""
    28	            Olá, %s!
    29	
    30	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
    31	
    32	            %s
    33	
    34	            A entrada é a partir das 14h, e a saída, até as 12h.
    35	            Até breve!""", reservation.guestName(), receipt);
    36	
    37	        messageSender.send(
    38	            MessageChannel.EMAIL,
    39	            reservation.guestEmail(),
    40	            "Reserva confirmada - Pousada Maré Alta",
    41	            body
    42	        );
    43	    }
    44	
    45	    private String buildReceipt(Reservation reservation) {
    46	        StringBuilder sb = new StringBuilder();
    47	        sb.append(String.format("Comprovante de reserva nº %d\n", reservation.id()));
    48	        sb.append(String.format("Hóspede: %s (CPF %s)\n",
    49	            reservation.guestName(), formatCpf(reservation.guestCpf())));
    50	        sb.append(String.format("Quarto: %d (%s)\n",
    51	            reservation.roomNumber(), reservation.roomType()));
    52	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n",
    53	            formatDate(reservation.checkIn()),
    54	            formatDate(reservation.checkOut()),
    55	            formatNights(reservation.nights())));
    56	        sb.append(String.format("Diárias: %s\n", formatMoney(reservation.subtotal())));
    57	        if (reservation.discount().compareTo(BigDecimal.ZERO) > 0) {
    58	            sb.append(String.format("Desconto: %s\n", formatMoney(reservation.discount())));
    59	        }
    60	        sb.append(String.format("Total: %s", formatMoney(reservation.total())));
    61	        return sb.toString();
    62	    }
    63	
    64	    private String formatCpf(String cpf) {
    65	        return cpf.replaceAll("(\\d{3})(\\d{3})(\\d{3})(\\d{2})", "$1.$2.$3-$4");
    66	    }
    67	
    68	    private String formatDate(LocalDate date) {
    69	        return date.format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));
    70	    }
    71	
    72	    private String formatNights(int nights) {
    73	        return nights == 1 ? "1 diária" : nights + " diárias";
    74	    }
    75	
    76	    private String formatMoney(BigDecimal amount) {
    77	        return String.format(Locale.of("pt", "BR"), "R$ %,.2f", amount);
    78	    }
    79	}
