     8	import com.pousadamarealta.repository.RoomRepository;
     9	
    10	import java.time.LocalDate;
    11	import java.util.List;
    12	
    13	public final class ReservationService {
    14	    private final RoomRepository roomRepository;
    15	    private final ReservationRepository reservationRepository;
    16	    private final PricingService pricingService;
    17	    private final List<ReservationListener> listeners;
    18	
    19	    public ReservationService(
    20	            RoomRepository roomRepository,
    21	            ReservationRepository reservationRepository,
    22	            PricingService pricingService,
    23	            List<ReservationListener> listeners) {
    24	        this.roomRepository = roomRepository;
    25	        this.reservationRepository = reservationRepository;
    26	        this.pricingService = pricingService;
    27	        this.listeners = List.copyOf(listeners);
    28	    }
    29	
    30	    public record CreateReservationRequest(
    31	        int roomNumber,
    32	        String guestName,
    33	        String guestEmail,
    34	        String guestCpf,
    35	        LocalDate checkIn,
    36	        LocalDate checkOut,
    37	        int guests,
    38	        RatePlan ratePlan
    39	    ) {}
    40	
    41	    public Reservation create(CreateReservationRequest request) {
    42	        Room room = roomRepository.findByNumber(request.roomNumber)
    43	            .orElseThrow(() -> new RoomNotFoundException("Room not found: " + request.roomNumber));
    44	
    45	        if (request.guests < 1) {
    46	            throw new InvalidRequestException("At least one guest is required");
    47	        }
    48	
    49	        if (request.guests > room.capacity()) {
    50	            throw new CapacityExceededException("Room capacity exceeded");
    51	        }
    52	
    53	        if (!request.checkOut.isAfter(request.checkIn)) {
    54	            throw new InvalidRequestException("Check-out must be after check-in");
    55	        }
    56	
    57	        if (!reservationRepository.isRoomAvailable(request.roomNumber, request.checkIn, request.checkOut, null)) {
    58	            throw new RoomUnavailableException("Room is not available for the selected dates");
    59	        }
    60	
    61	        PricingService.PricingResult pricing = pricingService.calculate(
    62	            room, request.checkIn, request.checkOut, request.ratePlan);
    63	
    64	        Reservation reservation = new Reservation(
    65	            reservationRepository.nextId(),
    66	            request.roomNumber,
    67	            room.type(),
    68	            request.guestName,
    69	            request.guestEmail,
    70	            request.guestCpf,
    71	            request.checkIn,
    72	            request.checkOut,
    73	            request.guests,
    74	            request.ratePlan,
    75	            pricing.nights(),
    76	            pricing.subtotal(),
    77	            pricing.discount(),
    78	            pricing.total()
    79	        );
    80	
    81	        return reservationRepository.save(reservation);
    82	    }
    83	
    84	    public Reservation confirm(int id) {
    85	        Reservation reservation = findById(id);
    86	        reservation.confirm();
    87	        notifyListeners(new ReservationEvent.Confirmed(reservation));
    88	        return reservation;
    89	    }
    90	
    91	    public Reservation cancel(int id) {
    92	        Reservation reservation = findById(id);
    93	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    94	        reservation.cancel();
    95	        notifyListeners(new ReservationEvent.Cancelled(reservation, wasConfirmed));
    96	        return reservation;
    97	    }
    98	
    99	    public Reservation checkIn(int id) {
   100	        Reservation reservation = findById(id);
   101	        reservation.performCheckIn();
   102	        return reservation;
   103	    }
   104	
   105	    public Reservation checkOut(int id) {
   106	        Reservation reservation = findById(id);
   107	        reservation.performCheckOut();
   108	        return reservation;
   109	    }
   110	
   111	    public Reservation findById(int id) {
   112	        return reservationRepository.findById(id)
   113	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found: " + id));
   114	    }
   115	
   116	    private void notifyListeners(ReservationEvent event) {
   117	        for (ReservationListener listener : listeners) {
   118	            listener.onEvent(event);
   119	        }
   120	    }
   121	
   122	    public static class RoomNotFoundException extends RuntimeException {
   123	        public RoomNotFoundException(String message) { super(message); }
   124	    }
   125	
   126	    public static class ReservationNotFoundException extends RuntimeException {
   127	        public ReservationNotFoundException(String message) { super(message); }
   128	    }
   129	
   130	    public static class InvalidRequestException extends RuntimeException {
   131	        public InvalidRequestException(String message) { super(message); }
   132	    }
   133	
   134	    public static class CapacityExceededException extends RuntimeException {
   135	        public CapacityExceededException(String message) { super(message); }
   136	    }
   137	
   138	    public static class RoomUnavailableException extends RuntimeException {
   139	        public RoomUnavailableException(String message) { super(message); }
   140	    }
   141	}
