    48	        sb.append(String.format("Hóspede: %s (CPF %s)\n",
    49	            reservation.guestName(), formatCpf(reservation.guestCpf())));
    50	        sb.append(String.format("Quarto: %d (%s)\n",
    51	            reservation.roomNumber(), reservation.roomType()));
    52	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n",
    53	            formatDate(reservation.checkIn()),
    54	            formatDate(reservation.checkOut()),
    55	            formatNights(reservation.nights())));
    56	        sb.append(String.format("Diárias: %s\n", formatMoney(reservation.subtotal())));
    57	        if (reservation.discount().compareTo(BigDecimal.ZERO) > 0) {
    58	            sb.append(String.format("Desconto: %s\n", formatMoney(reservation.discount())));
    59	        }
    60	        sb.append(String.format("Total: %s", formatMoney(reservation.total())));
    61	        return sb.toString();
    62	    }
    63	
    64	    private String formatCpf(String cpf) {
    65	        return cpf.replaceAll("(\\d{3})(\\d{3})(\\d{3})(\\d{2})", "$1.$2.$3-$4");
    66	    }
    67	
    68	    private String formatDate(LocalDate date) {
    69	        return date.format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));
    70	    }
