    30	    public record CreateReservationRequest(
    31	        int roomNumber,
    32	        String guestName,
    33	        String guestEmail,
    34	        String guestCpf,
    35	        LocalDate checkIn,
    36	        LocalDate checkOut,
    37	        int guests,
    38	        RatePlan ratePlan
    39	    ) {}
