    41	    public Reservation create(CreateReservationRequest request) {
    42	        Room room = roomRepository.findByNumber(request.roomNumber)
    43	            .orElseThrow(() -> new RoomNotFoundException("Room not found: " + request.roomNumber));
    44	
    45	        if (request.guests < 1) {
    46	            throw new InvalidRequestException("At least one guest is required");
    47	        }
    48	
    49	        if (request.guests > room.capacity()) {
    50	            throw new CapacityExceededException("Room capacity exceeded");
    51	        }
    52	
    53	        if (!request.checkOut.isAfter(request.checkIn)) {
    54	            throw new InvalidRequestException("Check-out must be after check-in");
    55	        }
    56	
    57	        if (!reservationRepository.isRoomAvailable(request.roomNumber, request.checkIn, request.checkOut, null)) {
    58	            throw new RoomUnavailableException("Room is not available for the selected dates");
    59	        }
    60	
    61	        PricingService.PricingResult pricing = pricingService.calculate(
    62	            room, request.checkIn, request.checkOut, request.ratePlan);
    63	
    64	        Reservation reservation = new Reservation(
    65	            reservationRepository.nextId(),
    66	            request.roomNumber,
    67	            room.type(),
    68	            request.guestName,
    69	            request.guestEmail,
    70	            request.guestCpf,
    71	            request.checkIn,
    72	            request.checkOut,
    73	            request.guests,
    74	            request.ratePlan,
    75	            pricing.nights(),
    76	            pricing.subtotal(),
    77	            pricing.discount(),
    78	            pricing.total()
    79	        );
    80	
    81	        return reservationRepository.save(reservation);
    82	    }
