  1	package com.pousadamarealta.domain;
  2	
  3	import java.math.BigDecimal;
  4	import java.time.LocalDate;
  5	
  6	public final class Reservation {
  7	    private final int id;
  8	    private final int roomNumber;
  9	    private final RoomType roomType;
 10	    private final String guestName;
 11	    private final String guestEmail;
 12	    private final String guestCpf;
 13	    private final LocalDate checkIn;
 14	    private final LocalDate checkOut;
 15	    private final int guests;
 16	    private final RatePlan ratePlan;
 17	    private final int nights;
 18	    private final BigDecimal subtotal;
 19	    private final BigDecimal discount;
 20	    private final BigDecimal total;
 21	    private ReservationStatus status;
 22	    private BigDecimal amountPaid;
 23	    private BigDecimal refund;
 24	
 25	    public Reservation(
 26	            int id,
 27	            int roomNumber,
 28	            RoomType roomType,
 29	            String guestName,
 30	            String guestEmail,
 31	            String guestCpf,
 32	            LocalDate checkIn,
 33	            LocalDate checkOut,
 34	            int guests,
 35	            RatePlan ratePlan,
 36	            int nights,
 37	            BigDecimal subtotal,
 38	            BigDecimal discount,
 39	            BigDecimal total) {
 40	        this.id = id;
 41	        this.roomNumber = roomNumber;
 42	        this.roomType = roomType;
 43	        this.guestName = guestName;
 44	        this.guestEmail = guestEmail;
 45	        this.guestCpf = guestCpf;
 46	        this.checkIn = checkIn;
 47	        this.checkOut = checkOut;
 48	        this.guests = guests;
 49	        this.ratePlan = ratePlan;
 50	        this.nights = nights;
 51	        this.subtotal = subtotal;
 52	        this.discount = discount;
 53	        this.total = total;
 54	        this.status = ReservationStatus.PENDING;
 55	        this.amountPaid = BigDecimal.ZERO;
 56	        this.refund = null;
 57	    }
 58	
 59	    public void confirm() {
 60	        if (status != ReservationStatus.PENDING) {
 61	            throw new IllegalStateException("Only pending reservations can be confirmed");
 62	        }
 63	        this.status = ReservationStatus.CONFIRMED;
 64	        this.amountPaid = total;
 65	    }
 66	
 67	    public void cancel() {
 68	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
 69	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
 70	        }
 71	        boolean wasConfirmed = status == ReservationStatus.CONFIRMED;
 72	        this.status = ReservationStatus.CANCELLED;
 73	        this.refund = wasConfirmed && ratePlan == RatePlan.STANDARD ? amountPaid : BigDecimal.ZERO;
 74	    }
 75	
 76	    public void performCheckIn() {
 77	        if (status != ReservationStatus.CONFIRMED) {
