122	
123	import java.math.BigDecimal;
124	import java.math.RoundingMode;
125	import java.time.LocalDate;
126	import java.time.Month;
127	
128	public final class PricingService {
129	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
130	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
131	
132	    public record PricingResult(
133	        int nights,
134	        BigDecimal subtotal,
135	        BigDecimal discount,
136	        BigDecimal total
137	    ) {}
138	
139	    public PricingResult calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
140	        int nights = (int) checkIn.datesUntil(checkOut).count();
141	        BigDecimal subtotal = BigDecimal.ZERO;
142	
143	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
144	            BigDecimal nightRate = room.nightlyRate();
145	            if (isHighSeason(date)) {
146	                nightRate = nightRate.multiply(HIGH_SEASON_MULTIPLIER);
147	            }
148	            nightRate = round(nightRate);
149	            subtotal = subtotal.add(nightRate);
150	        }
151	
152	        subtotal = round(subtotal);
153	
154	        BigDecimal discount = BigDecimal.ZERO;
155	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
156	            discount = round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
157	        }
158	
159	        BigDecimal total = round(subtotal.subtract(discount));
160	
161	        return new PricingResult(nights, subtotal, discount, total);
162	    }
163	
164	    private boolean isHighSeason(LocalDate date) {
165	        Month month = date.getMonth();
166	        int day = date.getDayOfMonth();
167	
168	        if (month == Month.DECEMBER && day >= 15) return true;
169	        if (month == Month.JANUARY || month == Month.FEBRUARY) return true;
170	        if (month == Month.JULY) return true;
171	
172	        return false;
173	    }
174	
175	    private BigDecimal round(BigDecimal value) {
176	        return value.setScale(2, RoundingMode.HALF_EVEN);
177	    }
178	}

